export class SourceControlPanel{
 constructor(element,{request,error=()=>{},open=()=>{},merge=()=>{}}){Object.assign(this,{element,request,error,open,merge});this.selected=new Set();this.path='';this.staged=false;this.epoch=0;this.diffEpoch=0;this.draftMessage='';this.refresh().catch(e=>this.failure(e));}
 async api(command,params={}){const response=await this.request('/api/source-control/'+command,{method:'POST',body:JSON.stringify(params)}),data=await response.json();if(!response.ok||data.error)throw Error(data.error||'소스 관리 요청 실패');return data;}
 failure(error){if(this.disposed)return;this.error(error.message);if(this.message)this.message.textContent=error.message;}
 async refresh(){const epoch=++this.epoch,status=await this.api('status');if(this.disposed||epoch!==this.epoch)return;this.status=status;this.selected=new Set([...this.selected].filter(p=>status.entries.some(e=>e.path===p)));this.render();}
 async action(command){if(this.busy)return;this.busy=true;try{const params={expectedIndexRevision:this.status.indexRevision};if(command==='stage'||command==='unstage'){params.paths=[...this.selected];params.unstage=command==='unstage';await this.api('stage',params);}else if(command==='commit'){params.message=this.commitMessage.value;await this.api('commit',params);this.draftMessage='';}else if(command==='init')await this.api('init');else if(command==='configure'){params.name=this.authorName.value;params.email=this.authorEmail.value;await this.api('configure',params);}await this.refresh();}catch(e){this.failure(e);}finally{this.busy=false;}}
 async diff(path,staged){this.path=path;this.staged=staged;const epoch=++this.diffEpoch;try{const diff=await this.api('diff',{path,staged});if(this.disposed||epoch!==this.diffEpoch)return;this.fileTitle.textContent=path+(staged?' · 스테이징':' · 작업 파일');this.code.textContent=diff.text.slice(0,524288);this.message.textContent=diff.bytes.toLocaleString()+' B'+(diff.binary?' · 이진 파일':'')+(diff.truncated||diff.text.length>524288?' · 미리보기 제한':'');}catch(e){this.failure(e);}}
 render(){
  const document=this.element.ownerDocument,status=this.status;this.element.className='workspace-view source-control-panel';this.element.replaceChildren();
  const header=document.createElement('header');header.className='document-toolbar';const title=document.createElement('strong');title.textContent=status.available?status.branch:'소스 관리';header.append(title);
  const button=(parent,label,action,disabled=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;b.onclick=action;parent.append(b);return b;};button(header,'새로고침',()=>this.refresh().catch(e=>this.failure(e)));if(!status.projectRoot)button(header,'프로젝트 저장소 만들기',()=>this.action('init'));this.element.append(header);
  const body=document.createElement('div');body.className='source-control-body';const files=document.createElement('aside'),detail=document.createElement('main');body.append(files,detail);this.element.append(body);
  const tools=document.createElement('div');tools.className='source-control-actions';button(tools,'스테이징',()=>this.action('stage'),!status.projectRoot);button(tools,'스테이징 취소',()=>this.action('unstage'),!status.projectRoot);files.append(tools);
  for(const [label,staged,entries]of [['스테이징',true,status.entries.filter(e=>!e.untracked&&e.index!==' ')],['작업 파일',false,status.entries.filter(e=>e.untracked||e.working!==' ')]]){const heading=document.createElement('h3');heading.textContent=label+' · '+entries.length;files.append(heading);for(const entry of entries){const row=document.createElement('div');row.className='source-control-file';const select=document.createElement('input');select.type='checkbox';select.checked=this.selected.has(entry.path);select.setAttribute('aria-label',entry.path+' 선택');select.onchange=()=>select.checked?this.selected.add(entry.path):this.selected.delete(entry.path);const name=button(row,entry.path,()=>this.diff(entry.path,staged));name.title=entry.path;name.ondblclick=()=>this.open(entry.path);const badge=document.createElement('small');badge.textContent=entry.conflict?'충돌':staged?entry.index:entry.working;row.prepend(select);row.append(badge);files.append(row);if(entry.conflict)button(files,'병합 · '+entry.path,()=>this.merge(entry.path));}}
  const commit=document.createElement('section');commit.className='source-control-commit';this.commitMessage=document.createElement('textarea');this.commitMessage.rows=3;this.commitMessage.value=this.draftMessage;this.commitMessage.oninput=()=>this.draftMessage=this.commitMessage.value;this.commitMessage.placeholder='변경 내용';this.commitMessage.setAttribute('aria-label','커밋 설명');commit.append(this.commitMessage);const identity=document.createElement('small');identity.textContent=[status.identity.name,status.identity.email].filter(Boolean).join(' · ');commit.append(identity);button(commit,'커밋',()=>this.action('commit'),!status.projectRoot||!status.entries.some(e=>!e.untracked&&e.index!==' '));
  const settings=document.createElement('details'),summary=document.createElement('summary');summary.textContent='작성자';settings.append(summary);for(const [key,label,value]of [['authorName','이름',status.identity.name],['authorEmail','이메일',status.identity.email]]){const line=document.createElement('label'),input=document.createElement('input');line.textContent=label;input.value=value;input.setAttribute('aria-label','Git '+label);this[key]=input;line.append(input);settings.append(line);}button(settings,'저장',()=>this.action('configure'),!status.projectRoot);commit.append(settings);files.append(commit);
  this.fileTitle=document.createElement('h3');this.fileTitle.textContent=this.path||'변경 비교';this.code=document.createElement('pre');this.code.tabIndex=0;this.code.setAttribute('aria-label','Git 변경 내용');this.message=document.createElement('small');detail.append(this.fileTitle,this.code,this.message);if(this.path&&status.entries.some(e=>e.path===this.path))this.diff(this.path,this.staged);
 }
 dispose(){this.disposed=true;this.epoch++;this.diffEpoch++;this.element.replaceChildren();}
}
